        System.out.println("After Carol's no-op unlike: " + likeService.approximateCount("post-1"));

        System.out.println("Final count is exactly one, from Alice's single genuine like: " + (likeService.approximateCount("post-1") == 1));
    }
}

// One post's counter, represented as several independent shards that
// can each be incremented without contending with each other.
class ShardedCounter {
    private final AtomicLong[] shards; // independent, lock free counters

    public ShardedCounter(int shardCount) {
        shards = new AtomicLong[shardCount];                          // allocate the shard array
        for (int i = 0; i < shardCount; i++) shards[i] = new AtomicLong(0); // every shard starts at zero
    }

    // Routes an increment to one shard, chosen by hashing the acting user's id
    // so load spreads evenly rather than concentrating on one shard.
    public void increment(String userId) {
        int index = Math.floorMod(userId.hashCode(), shards.length); // which shard this user's action lands on
        shards[index].incrementAndGet();                                // bump that shard only
    }

    public void decrement(String userId) {
        int index = Math.floorMod(userId.hashCode(), shards.length); // same routing as increment
        shards[index].decrementAndGet();                                // reduce that shard only
    }

    // Sums every shard to produce the true current total. Cheap, but still
    // not free, which is exactly why callers cache this rather than call it
    // on every single read.
    public long readTotal() {
        long total = 0;                                    // running sum across every shard
        for (AtomicLong shard : shards) total += shard.get(); // add each shard's current value
        return total;                                          // the true total right now
    }
}

// Guarantees a like or unlike from the same user on the same post only
// ever takes effect once, regardless of retries or duplicate requests.
class LikeService {
    private final Map<String, Set<String>> likedByUserForPost = new ConcurrentHashMap<>(); // postId -> set of userIds who have liked it
    private final Map<String, ShardedCounter> counterByPost = new ConcurrentHashMap<>();      // postId -> its sharded counter

    public void like(String postId, String userId) {
        Set<String> likedUsers = likedByUserForPost.computeIfAbsent(postId, id -> ConcurrentHashMap.newKeySet()); // this post's like set
        boolean firstTime = likedUsers.add(userId); // returns false if userId was already present
        if (!firstTime) {
            return; // already liked, this call has no additional effect
        }
        ShardedCounter counter = counterByPost.computeIfAbsent(postId, id -> new ShardedCounter(defaultShardCountFor(postId))); // this post's counter
        counter.increment(userId); // count this genuinely new like
    }

    public void unlike(String postId, String userId) {
        Set<String> likedUsers = likedByUserForPost.get(postId); // this post's like set, if it exists
        if (likedUsers == null || !likedUsers.remove(userId)) {
            return; // was never liked, nothing to undo
        }
        ShardedCounter counter = counterByPost.get(postId); // this post's counter
        if (counter != null) counter.decrement(userId);        // reverse the earlier increment
    }

    public long approximateCount(String postId) {
        ShardedCounter counter = counterByPost.get(postId);          // this post's counter, if it exists
        return counter == null ? 0 : counter.readTotal();               // zero if nobody has liked it yet
    }

    private int defaultShardCountFor(String postId) {
        return 8; // small default, grown dynamically as a post's write rate rises
    }
}

