#include <atomic>
#include <functional>
#include <iostream>
#include <map>
#include <mutex>
#include <set>
#include <string>
#include <vector>

// One post's counter, represented as several independent shards that
// can each be incremented without contending with each other.
class ShardedCounter {
public:
    explicit ShardedCounter(int shardCount) : shards_(shardCount) {
        for (auto& s : shards_) s = 0;
    }

    // Routes an increment to one shard, chosen by hashing the acting user's id
    // so load spreads evenly rather than concentrating on one shard.
    void increment(const std::string& userId) {
        size_t index = std::hash<std::string>{}(userId) % shards_.size();   // which shard this user's action lands on
        shards_[index]++;                                                     // bump that shard only
    }
    void decrement(const std::string& userId) {
        size_t index = std::hash<std::string>{}(userId) % shards_.size();   // same routing as increment
        shards_[index]--;                                                     // reduce that shard only
    }

    // Sums every shard to produce the true current total. Cheap, but still
    // not free, which is exactly why callers cache this rather than call it
    // on every single read.
    long readTotal() {
        long total = 0;                                    // running sum across every shard
        for (auto& s : shards_) total += s.load();             // add each shard's current value
        return total;                                          // the true total right now
    }

private:
    std::vector<std::atomic<long>> shards_;   // independent, lock free counters
};

// Guarantees a like or unlike from the same user on the same post only
// ever takes effect once, regardless of retries or duplicate requests.
class LikeService {
public:
    void like(const std::string& postId, const std::string& userId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& likedUsers = likedByUserForPost_[postId];             // this post's like set
        bool firstTime = likedUsers.find(userId) == likedUsers.end();   // false if userId was already present
        likedUsers.insert(userId);
        if (!firstTime) return;                                          // already liked, this call has no additional effect
        if (counterByPost_.find(postId) == counterByPost_.end()) {
            counterByPost_.emplace(postId, defaultShardCountFor(postId));   // this post's counter
        }
        counterByPost_.at(postId).increment(userId);                        // count this genuinely new like
    }

    void unlike(const std::string& postId, const std::string& userId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = likedByUserForPost_.find(postId);                     // this post's like set, if it exists
        if (it == likedByUserForPost_.end() || it->second.erase(userId) == 0) {
            return;                                                          // was never liked, nothing to undo
        }
        auto cit = counterByPost_.find(postId);                         // this post's counter
        if (cit != counterByPost_.end()) cit->second.decrement(userId);     // reverse the earlier increment
    }

    long approximateCount(const std::string& postId) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = counterByPost_.find(postId);                          // this post's counter, if it exists
        return it == counterByPost_.end() ? 0 : it->second.readTotal();     // zero if nobody has liked it yet
    }

private:
    int defaultShardCountFor(const std::string&) { return 8; }   // small default, grown dynamically as a post's write rate rises

    std::map<std::string, std::set<std::string>> likedByUserForPost_;   // postId -> set of userIds who have liked it
    std::map<std::string, ShardedCounter> counterByPost_;                  // postId -> its sharded counter
    std::mutex mutex_;
};

int main() {
    std::cout << std::boolalpha;
    LikeService likeService;   // the whole like counting system

    likeService.like("post-1", "alice");   // alice's first, genuine like
    std::cout << "After Alice likes: " << likeService.approximateCount("post-1") << "\n";

    likeService.like("post-1", "alice");   // alice retries or double taps
    std::cout << "After Alice likes again (duplicate): " << likeService.approximateCount("post-1") << "\n";

    likeService.like("post-1", "bob");   // bob's first, genuine like
    std::cout << "After Bob likes: " << likeService.approximateCount("post-1") << "\n";

    likeService.unlike("post-1", "bob");   // bob changes his mind
    std::cout << "After Bob unlikes: " << likeService.approximateCount("post-1") << "\n";

    likeService.unlike("post-1", "carol");   // carol never liked this post
    std::cout << "After Carol's no-op unlike: " << likeService.approximateCount("post-1") << "\n";

    std::cout << "Final count is exactly one, from Alice's single genuine like: "
              << (likeService.approximateCount("post-1") == 1) << "\n";
    return 0;
}

